import{K as e,Lt as t,Mt as n,Ot as r,Q as i,V as a,ht as o,nt as s,tt as c}from"./chunks/framework.wxcks8ca.js";var l={class:`oc-tabs`},u={class:`oc-panel`},d={class:`oc-panel`},f=JSON.parse(`{"title":"Kimi Code 概览","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"zh/index.md"}`),p=a(Object.assign({name:`index.md`},{setup(a){let f=n(`cli`);return(n,a)=>(o(),c(`div`,null,[a[4]||=s(`<h1 id="kimi-code-概览" tabindex="-1" data-v-16a06b70>Kimi Code 概览 <a class="header-anchor" href="#kimi-code-概览" aria-label="Permalink to “Kimi Code 概览”" data-v-16a06b70>​</a></h1><h2 id="kimi-code-是什么" tabindex="-1" data-v-16a06b70>Kimi Code 是什么 <a class="header-anchor" href="#kimi-code-是什么" aria-label="Permalink to “Kimi Code 是什么”" data-v-16a06b70>​</a></h2><p data-v-16a06b70>Kimi Code 是 <a href="https://www.kimi.com/membership/pricing?from=kfc_docs_overview" target="_blank" rel="noreferrer" data-v-16a06b70>Kimi 会员权益</a>中专为开发者提供的智能编程服务，基于 Kimi 最新旗舰模型，通过 CLI、VS Code 扩展插件等产品形态，为开发者提供代码阅读、文件编辑、命令执行等 AI 辅助能力。同时，订阅用户可获取 API Key，将 Kimi Code 的模型能力接入到第三方开发工具与平台。</p><h2 id="核心优势" tabindex="-1" data-v-16a06b70>核心优势 <a class="header-anchor" href="#核心优势" aria-label="Permalink to “核心优势”" data-v-16a06b70>​</a></h2><ul data-v-16a06b70><li data-v-16a06b70><strong data-v-16a06b70>底层模型持续升级</strong>：紧跟 Kimi 最新旗舰模型，持续获得前沿代码理解、推理与生成能力</li><li data-v-16a06b70><strong data-v-16a06b70>双档速度自由切换</strong>：同一模型提供普通版与高速版，高速版输出速度约为普通版的 5–6 倍，按任务节奏一键选择</li><li data-v-16a06b70><strong data-v-16a06b70>广泛兼容</strong>：完美适配 Kimi Code CLI、VS Code、Claude Code 等各类开发工具</li><li data-v-16a06b70><strong data-v-16a06b70>极速响应</strong>：最高输出速度可达 100 Tokens/s</li><li data-v-16a06b70><strong data-v-16a06b70>高频并发</strong>：每 5 小时支持约 300–1200 次请求，最高并发 30</li></ul><h2 id="开始使用" tabindex="-1" data-v-16a06b70>开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to “开始使用”" data-v-16a06b70>​</a></h2><p data-v-16a06b70>Kimi Code 支持会员在官方客户端和第三方平台使用权益，覆盖不同的开发场景。</p><h3 id="使用官方客户端" tabindex="-1" data-v-16a06b70>使用官方客户端 <a class="header-anchor" href="#使用官方客户端" aria-label="Permalink to “使用官方客户端”" data-v-16a06b70>​</a></h3><p data-v-16a06b70>选择适合你的客户端，一键安装：</p>`,9),i(`div`,l,[i(`button`,{class:t([`oc-tab`,{active:f.value===`cli`}]),onClick:a[0]||=e=>f.value=`cli`},`Kimi Code CLI`,2),i(`button`,{class:t([`oc-tab`,{active:f.value===`vscode`}]),onClick:a[1]||=e=>f.value=`vscode`},`Kimi Code for VS Code`,2)]),r(i(`div`,u,[...a[2]||=[s(`<p data-v-16a06b70>适合习惯终端操作的开发者。在终端中与 AI 对话，让它阅读代码、编辑文件、执行命令、搜索网页，自主完成开发任务。</p><div class="warning custom-block" data-v-16a06b70><p class="custom-block-title" data-v-16a06b70>📢 CLI 已升级</p><p data-v-16a06b70>Kimi Code CLI 已完成重大版本升级，底层从 Python/uv 迁移至 Node.js，带来更简单的安装方式、更快的启动速度和全新的终端界面。旧版将不再维护。查看 <a href="/code/docs/kimi-code-cli/guides/migration.html" data-v-16a06b70>版本升级</a> 了解详情和迁移方式，如需参考旧版内容，请查阅 Python 版 Kimi Code <a href="https://moonshotai.github.io/kimi-cli/zh/" target="_blank" rel="noreferrer" data-v-16a06b70>文档站</a>。</p></div><div class="language-bash" data-v-16a06b70><button title="Copy Code" class="copy" data-v-16a06b70></button><span class="lang" data-v-16a06b70>bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr" data-v-16a06b70><code data-v-16a06b70><span class="line" data-v-16a06b70><span style="--shiki-light:#62687b;--shiki-dark:#818e99;" data-v-16a06b70># macOS / Linux</span></span>
<span class="line" data-v-16a06b70><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-16a06b70>curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-16a06b70> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-16a06b70> https://code.kimi.com/kimi-code/install.sh</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;" data-v-16a06b70> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-16a06b70> bash</span></span></code></pre></div><div class="language-powershell" data-v-16a06b70><button title="Copy Code" class="copy" data-v-16a06b70></button><span class="lang" data-v-16a06b70>powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr" data-v-16a06b70><code data-v-16a06b70><span class="line" data-v-16a06b70><span style="--shiki-light:#62687b;--shiki-dark:#818e99;" data-v-16a06b70># Windows (PowerShell)</span></span>
<span class="line" data-v-16a06b70><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-16a06b70>irm https:</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;" data-v-16a06b70>//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-16a06b70>code.kimi.com</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;" data-v-16a06b70>/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-16a06b70>kimi</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;" data-v-16a06b70>-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-16a06b70>code</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;" data-v-16a06b70>/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-16a06b70>install.ps1 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;" data-v-16a06b70>|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-16a06b70> iex</span></span></code></pre></div><p data-v-16a06b70>安装完成后，在终端中运行 <code data-v-16a06b70>kimi</code> 启动，首次使用通过 <code data-v-16a06b70>/login</code> 命令登录 Kimi Code 平台即完成接入，无需手动管理 API Key。</p>`,5)]],512),[[e,f.value===`cli`]]),r(i(`div`,d,[...a[3]||=[s(`<p data-v-16a06b70>适合偏好使用 VS Code 编辑器的开发者。在编辑器侧边栏与 AI 协同，支持代码补全、文件编辑、网页搜索和自动化任务。</p><div class="warning custom-block" data-v-16a06b70><p class="custom-block-title" data-v-16a06b70>VS Code 插件适配中</p><p data-v-16a06b70>Kimi Code for VS Code 目前仅对旧版 Python CLI 用户开放新增安装。已安装插件的老用户升级新版 CLI 后仍可继续使用，其他 TS 版本 CLI 用户暂不支持安装。</p></div><p data-v-16a06b70>在 VS Code 扩展市场搜索 &quot;Kimi Code&quot; 安装，或访问 <a href="vscode:extension/moonshot-ai.kimi-code" target="_blank" rel="noreferrer" data-v-16a06b70>Visual Studio Marketplace</a>。安装后通过侧边栏的登录按钮完成接入，无需手动管理 API Key。</p><blockquote data-v-16a06b70><p data-v-16a06b70>若安装后未显示扩展，请重启 VS Code 或在命令面板中执行 &quot;Developer: Reload Window&quot; (Mac: Cmd+Shift+P, Windows/Linux: Ctrl+Shift+P)。</p></blockquote><p data-v-16a06b70>其他编辑器如 JetBrains、Zed 可通过 CLI 的 ACP 协议接入使用，详见 <a href="/code/docs/kimi-code-cli/guides/ides.html" data-v-16a06b70>在 IDE 中使用</a>。</p>`,5)]],512),[[e,f.value===`vscode`]]),a[5]||=s(`<h3 id="api-接入" tabindex="-1" data-v-16a06b70>API 接入 <a class="header-anchor" href="#api-接入" aria-label="Permalink to “API 接入”" data-v-16a06b70>​</a></h3><p data-v-16a06b70>将 Kimi Code 接入第三方开发工具时，需要手动配置 API Key 完成认证。</p><h4 id="服务地址" tabindex="-1" data-v-16a06b70>服务地址 <a class="header-anchor" href="#服务地址" aria-label="Permalink to “服务地址”" data-v-16a06b70>​</a></h4><p data-v-16a06b70>Kimi Code API 同时兼容 OpenAI 和 Anthropic 两种协议。不同工具对地址配置的要求不同：</p><ul data-v-16a06b70><li data-v-16a06b70><strong data-v-16a06b70>Base URL</strong>：部分工具（如 Claude Code）只需填写 Base URL，工具会自动拼接后续路径。</li><li data-v-16a06b70><strong data-v-16a06b70>完整 Endpoint</strong>：部分工具（如 Trae）需要填写完整的 API 请求地址。</li></ul><p data-v-16a06b70>按需选择对应的地址：</p><table tabindex="0" data-v-16a06b70><thead data-v-16a06b70><tr data-v-16a06b70><th data-v-16a06b70>协议</th><th data-v-16a06b70>Base URL</th><th data-v-16a06b70>常用 Endpoint 示例</th></tr></thead><tbody data-v-16a06b70><tr data-v-16a06b70><td data-v-16a06b70>OpenAI 兼容</td><td data-v-16a06b70><code data-v-16a06b70>https://api.kimi.com/coding/v1</code></td><td data-v-16a06b70><code data-v-16a06b70>https://api.kimi.com/coding/v1/chat/completions</code></td></tr><tr data-v-16a06b70><td data-v-16a06b70>Anthropic 兼容</td><td data-v-16a06b70><code data-v-16a06b70>https://api.kimi.com/coding/</code></td><td data-v-16a06b70><code data-v-16a06b70>https://api.kimi.com/coding/v1/messages</code></td></tr></tbody></table><h4 id="模型-id" tabindex="-1" data-v-16a06b70>模型 ID <a class="header-anchor" href="#模型-id" aria-label="Permalink to “模型 ID”" data-v-16a06b70>​</a></h4><p data-v-16a06b70>不同模型 ID 对应不同的会员档位与上下文窗口，具体权益见 <a href="/code/docs/kimi-code/membership.html" data-v-16a06b70>会员权益</a>。</p><p data-v-16a06b70>两种协议均可使用以下 4 个模型 ID：</p><table tabindex="0" data-v-16a06b70><thead data-v-16a06b70><tr data-v-16a06b70><th data-v-16a06b70>Model ID</th><th data-v-16a06b70>说明</th></tr></thead><tbody data-v-16a06b70><tr data-v-16a06b70><td data-v-16a06b70><code data-v-16a06b70>k3</code></td><td data-v-16a06b70>Kimi K3，Moderato 及以上会员可调用，Allegretto 及以上会员可解锁最高 100 万上下文；支持 <code data-v-16a06b70>low</code> / <code data-v-16a06b70>high</code> / <code data-v-16a06b70>max</code> 三档思考强度，适合大型代码库分析、多文件重构、超长文档处理等长上下文任务。</td></tr><tr data-v-16a06b70><td data-v-16a06b70><code data-v-16a06b70>k3-256k</code></td><td data-v-16a06b70>Kimi K3 256K 上下文版，Moderato 及以上会员可调用；支持 <code data-v-16a06b70>low</code> / <code data-v-16a06b70>high</code> / <code data-v-16a06b70>max</code> 三档思考强度。<code data-v-16a06b70>k3-256k</code>全新上线，256k上下文内效果相同, <code data-v-16a06b70>k3</code>（1M）消耗约为 <code data-v-16a06b70>k3-256k</code> 两倍，适合日常问答、代码补全、常规功能开发、单文件或少量文件修场景，不支持视频输入。</td></tr><tr data-v-16a06b70><td data-v-16a06b70><code data-v-16a06b70>kimi-for-coding</code></td><td data-v-16a06b70>Kimi K2.7 Code，所有会员可用。</td></tr><tr data-v-16a06b70><td data-v-16a06b70><code data-v-16a06b70>kimi-for-coding-highspeed</code></td><td data-v-16a06b70>Kimi K2.7 Code 高速版，Allegretto 及以上会员可用。</td></tr></tbody></table><p data-v-16a06b70>模型能力与配置细节见 <a href="/code/docs/kimi-code/models.html" data-v-16a06b70>模型配置</a>。</p><h4 id="获取-api-key" tabindex="-1" data-v-16a06b70>获取 API Key <a class="header-anchor" href="#获取-api-key" aria-label="Permalink to “获取 API Key”" data-v-16a06b70>​</a></h4><p data-v-16a06b70>Kimi 会员可在 <a href="https://www.kimi.com/code/console" target="_blank" rel="noreferrer" data-v-16a06b70>Kimi Code 控制台</a> 创建和管理（最多 5 个，仅创建时显示一次，请妥善保存）。</p><h4 id="配置到第三方工具" tabindex="-1" data-v-16a06b70>配置到第三方工具 <a class="header-anchor" href="#配置到第三方工具" aria-label="Permalink to “配置到第三方工具”" data-v-16a06b70>​</a></h4><p data-v-16a06b70>获取 API Key 后，将对应 Base URL 和 API Key 配置到对应工具的环境变量即可使用。详细配置步骤请参考对应工具的接入文档：</p><div class="tool-card-grid" data-v-16a06b70><a href="/code/docs/third-party-tools/claude-code" class="tool-card" data-v-16a06b70><span class="tool-card-icon" data-v-16a06b70><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" data-v-16a06b70><polyline points="8 7 4 12 8 17" data-v-16a06b70></polyline><polyline points="16 7 20 12 16 17" data-v-16a06b70></polyline></svg></span><span class="tool-card-title" data-v-16a06b70>Claude Code</span><span class="tool-card-desc" data-v-16a06b70>Anthropic 的命令行编程助手</span></a><a href="/code/docs/third-party-tools/opencode" class="tool-card" data-v-16a06b70><span class="tool-card-icon" data-v-16a06b70><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" data-v-16a06b70><rect x="3" y="5" width="18" height="14" rx="2" data-v-16a06b70></rect><polyline points="7 10 10 13 7 16" data-v-16a06b70></polyline><line x1="13" y1="13" x2="17" y2="13" data-v-16a06b70></line></svg></span><span class="tool-card-title" data-v-16a06b70>OpenCode</span><span class="tool-card-desc" data-v-16a06b70>终端编程 Agent</span></a><a href="/code/docs/third-party-tools/codex" class="tool-card" data-v-16a06b70><span class="tool-card-icon" data-v-16a06b70><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" data-v-16a06b70><path d="M12 2l8.66 5v10L12 22l-8.66-5V7L12 2z" data-v-16a06b70></path><path d="M12 12l8.66-5" data-v-16a06b70></path><path d="M12 12V2" data-v-16a06b70></path></svg></span><span class="tool-card-title" data-v-16a06b70>Codex</span><span class="tool-card-desc" data-v-16a06b70>OpenAI 的编程 Agent</span></a></div><blockquote data-v-16a06b70><p data-v-16a06b70><strong data-v-16a06b70>注意</strong>：使用时请保持工具的真实身份标识，篡改客户端标识（User-Agent）将被视为违规，可能导致会员权益暂停。</p></blockquote><h2 id="平台对比" tabindex="-1" data-v-16a06b70>平台对比 <a class="header-anchor" href="#平台对比" aria-label="Permalink to “平台对比”" data-v-16a06b70>​</a></h2><p data-v-16a06b70>Kimi Code 会员权益专为编程场景设计。如需在自己的产品中调用大模型能力，或需要团队协作与用量管理，请访问 <a href="https://platform.kimi.com" target="_blank" rel="noreferrer" data-v-16a06b70>Kimi 开放平台</a>。</p><table tabindex="0" data-v-16a06b70><thead data-v-16a06b70><tr data-v-16a06b70><th data-v-16a06b70>对比项</th><th data-v-16a06b70>Kimi Code 平台</th><th data-v-16a06b70>Kimi 开放平台</th></tr></thead><tbody data-v-16a06b70><tr data-v-16a06b70><td data-v-16a06b70>Base URL</td><td data-v-16a06b70>Open AI 兼容： <code data-v-16a06b70>https://api.kimi.com/coding/v1</code><br data-v-16a06b70> Anthropic 兼容：<code data-v-16a06b70>https://api.kimi.com/coding/</code></td><td data-v-16a06b70><code data-v-16a06b70>https://api.moonshot.cn/v1</code></td></tr><tr data-v-16a06b70><td data-v-16a06b70>计费方式</td><td data-v-16a06b70>会员订阅，按月/年付费，有频控限制</td><td data-v-16a06b70>按量付费，充值即用</td></tr><tr data-v-16a06b70><td data-v-16a06b70>最佳场景</td><td data-v-16a06b70>终端/IDE Agent 编程、多文件工程任务</td><td data-v-16a06b70>产品集成、企业级调用、多模态应用开发</td></tr></tbody></table><h2 id="下一步" tabindex="-1" data-v-16a06b70>下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”" data-v-16a06b70>​</a></h2><ul data-v-16a06b70><li data-v-16a06b70><a href="/code/docs/kimi-code-cli/guides/getting-started.html" data-v-16a06b70>Kimi Code CLI 快速开始</a> – 安装、登录、第一次对话</li><li data-v-16a06b70><a href="/code/docs/kimi-code-for-vscode/getting-started.html" data-v-16a06b70>Kimi Code for VS Code 快速开始</a> – 安装扩展、登录、典型工作流</li><li data-v-16a06b70><a href="/code/docs/third-party-tools/claude-code.html" data-v-16a06b70>在更多第三方工具中使用</a> – Claude Code、OpenCode、Codex 等</li><li data-v-16a06b70><a href="/code/docs/kimi-code/membership.html" data-v-16a06b70>会员权益</a> – 额度刷新与频率限制、配额共享、加油包等</li><li data-v-16a06b70><a href="/code/docs/kimi-code/faq.html" data-v-16a06b70>常见问题</a> – 安装、登录、使用中的常见问题</li></ul>`,23)]))}}),[[`__scopeId`,`data-v-16a06b70`]]);export{f as __pageData,p as default};